<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;
class StoreEmployeRequest extends FormRequest { public function authorize():bool{return $this->user()?->can('createEmployees')??false;} public function rules():array{return ['matricule'=>'nullable|string|max:50','nom'=>'required|string|max:120','postnom'=>'nullable|string|max:120','prenom'=>'nullable|string|max:120','sexe'=>'nullable|in:Homme,Femme,Autre','date_naissance'=>'nullable|date|before:today','lieu_naissance'=>'nullable|string|max:120','etat_civil'=>'nullable|string|max:30','nationalite'=>'nullable|string|max:80','adresse'=>'nullable|string','telephone'=>'nullable|string|max:40','email'=>'nullable|email|max:190','date_embauche'=>'nullable|date','departement_id'=>'nullable|exists:departements,id','service_id'=>'nullable|exists:rh_services,id','fonction_id'=>['nullable',Rule::exists('fonctions','id')->where('actif',true)],'superieur_id'=>'nullable|exists:rh_employes,id','site_id'=>'nullable|exists:rh_sites,id','statut'=>'required|in:Brouillon,Actif,En congé,Suspendu,Sorti,Retraité,Archivé','date_depart'=>'nullable|required_if:statut,Sorti,Retraité,Archivé|date|after_or_equal:date_embauche','motif_depart'=>'nullable|string','mode_paiement'=>'nullable|in:Espèces,Virement,Mobile money','user_id'=>'nullable|exists:users,id|unique:rh_employes,user_id'];} }
